// $EST framing for analysis/estimation's run_estimation (module-local
// Estimation.fbs, through flatc's object-API bindings generated by the site
// build). Encoding and decoding only; the estimators are the module's.
import * as flatbuffers from 'flatbuffers';
import {
  EstimationConfigT, EstimationEnvelope, EstimationEpochT, EstimationObservationT, EstimationPropagatorSampleT, EstimationRequest,
  EstimatorKind, MeasurementKind, ProcessNoiseKind,
} from '@estimation/orbpro/estimation';
import { ReferenceFrame } from '@estimation/orbpro/propagator';

export const EST_TYPE = { schemaName: 'Estimation.fbs', fileIdentifier: '$EST', rootTypeName: 'EstimationEnvelope', wireFormat: 'flatbuffer' };
export { EstimatorKind, MeasurementKind };

// UTC as {jd_day: the day's 0h, seconds into it}; one time scale throughout
// a request (station positions are supplied, so no Earth rotation is implied).
export function epochOf(ms, dayMs) {
  return new EstimationEpochT(dayMs / 86400e3 + 2440587.5, (ms - dayMs) / 1000);
}

// o: {ms, kind: 'RANGE' | 'RANGE_RATE' | 'RIGHT_ASCENSION_DECLINATION', values [SI], sigmas [SI],
//     stationPosition [m], stationVelocity [m/s]} (GCRF).
export function observation(o, dayMs) {
  const pad = (a) => [...a, 0, 0, 0, 0].slice(0, 4);
  const zero = [0, 0, 0];
  return new EstimationObservationT(epochOf(o.ms, dayMs), pad(o.values), pad(o.sigmas), o.stationPosition, o.stationVelocity, zero, zero, zero, zero, zero,
    0, 0, 0, 0, 0, 0, 0, 1013.25, 288.15, 0.5, 0, 0, 0, 1, 1, MeasurementKind[o.kind], o.values.length, 3, 0, 0);
}

// The request and the caller-supplied propagator samples (one per
// observation: state [m, m/s] and the cumulative STM from the initial epoch).
export function estimationInputs({ estimator, epochMs, dayMs, state, covariance, observations, samples, processNoise, sigmaEdit = 1e6 }) {
  const config = new EstimationConfigT(epochOf(epochMs, dayMs), state, covariance, processNoise ?? [0, 0, 0, 0, 0, 0], 1e-4, 1e-8, sigmaEdit, 0, 20,
    ReferenceFrame.ICRF, EstimatorKind[estimator], processNoise ? ProcessNoiseKind.STATE_NOISE_COMPENSATION : ProcessNoiseKind.NONE, 0);
  // Packed by hand: the object API writes every vector, even an empty one,
  // and an extended_observations vector (even empty) selects the extended
  // sequential path.
  const finishEnvelope = (add) => {
    const b = new flatbuffers.Builder(1 << 16);
    const offset = add(b);
    b.finish(offset, '$EST');
    return b.asUint8Array().slice();
  };
  const request = finishEnvelope((b) => {
    const cfg = config;
    const list = observations.map((o) => observation(o, dayMs));
    const obs = b.createStructOffsetList(list, EstimationRequest.startObservationsVector);
    const port = b.createString('propagator/hpop'), capability = b.createString('plugin_propagate plugin_compute_stm'), trace = b.createString('od-pages');
    EstimationRequest.startEstimationRequest(b);
    EstimationRequest.addConfig(b, cfg.pack(b));
    EstimationRequest.addObservations(b, obs);
    EstimationRequest.addPropagatorPortId(b, port);
    EstimationRequest.addPropagatorCapability(b, capability);
    EstimationRequest.addTraceId(b, trace);
    const r = EstimationRequest.endEstimationRequest(b);
    EstimationEnvelope.startEstimationEnvelope(b);
    EstimationEnvelope.addRequest(b, r);
    return EstimationEnvelope.endEstimationEnvelope(b);
  });
  const sampleBytes = finishEnvelope((b) => {
    const list = samples.map((x) => new EstimationPropagatorSampleT(epochOf(x.ms, dayMs), x.state, x.stm));
    const v = b.createStructOffsetList(list, EstimationEnvelope.startPropagatorSamplesVector);
    EstimationEnvelope.startEstimationEnvelope(b);
    EstimationEnvelope.addPropagatorSamples(b, v);
    return EstimationEnvelope.endEstimationEnvelope(b);
  });
  return [
    { portId: 'request', typeRef: EST_TYPE, payload: request },
    { portId: 'propagator_samples', typeRef: EST_TYPE, payload: sampleBytes },
  ];
}

export function decodeEstimation(response) {
  const frame = response.outputs.find((o) => o.portId === 'result');
  const envelope = EstimationEnvelope.getRootAsEstimationEnvelope(new flatbuffers.ByteBuffer(new Uint8Array(frame.payload))).unpack();
  const result = envelope.result;
  if (!result) throw new Error('analysis/estimation: no result');
  return result;
}
